import html,json
from pathlib import Path
ROOT=Path(__file__).parent;E=html.escape
r=json.loads((ROOT/'evaluation.json').read_text());a=json.loads((ROOT/'audit.json').read_text())
notes={
'M1':('Checks the unused condition and known delivery age.','Conditional return; asks whether unused.'),
'M2':('Gives recorded status and estimate, without a guarantee.','Recorded status; no promised arrival date.'),
'M3':('Missing manager approval for the refund.','Asks for reference and photo; names support and manager responsibilities.'),
'M4':('Explains the time window, but leaves the used-item condition implicit.','Both eligibility failures explained; exception needs manager approval.'),
'M5':('English reply and redundant condition question.','French reply; known unused condition; practical steps left to support.'),
'V6':('Unknown reference; asks for correction or proof of purchase.','Unknown status; clarification requested; no invented date.'),
'V7':('Repeats supplied details and omits manager approval.','Does not repeat supplied details; damage review and manager approval.'),
'V8':('Misses the delivery question for A102.','Both questions and orders covered; no promise for tomorrow.'),
'V9':('Missing details needed to establish the return window.','Asks for reference, condition and delivery timing.'),
'V10':('Refund request not explicitly addressed.','Exception and refund both require manager approval.'),
'V11':('Refund claim not addressed.','No delivery guarantee or claim of an issued refund.'),
'V12':('Misses unknown order and refund; repeats reference; wrong language.','French; asks for photo and corrected reference; manager owns refund approval.')}
css='body{background:#f7f6f0;color:#153f35;font:15px/1.55 system-ui;margin:auto;max-width:1080px;padding:40px}h1{font:40px Georgia}h2{font:23px Georgia;margin:26px 0 10px}p{margin:0 0 12px}table{border-collapse:collapse;width:100%;font-size:12px}td,th{border-bottom:1px solid #dce1d8;padding:12px;text-align:left;vertical-align:top}details{margin:10px 0;background:white;padding:15px}pre{white-space:pre-wrap;font-size:12px}.muted{font-size:12px;color:#626d66}@media print{body{background:white;padding:0;font-size:11px}h1{font-size:28px}td,th{padding:6px}table{font-size:9px}}'
parts=['<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Maison Rue · Project appendix</title><style>'+css+'</style><body><p class="muted">HEC MSc DSAIB · CASE 01</p><h1>Maison Rue</h1><h2>What we built</h2><p>A small drafting assistant for the shop’s two support colleagues. It reads an enquiry against the provided policies and order snapshot, drafts a reply in the customer’s language and separates supporting facts, missing information and proposed next steps.</p><h2>Design and value</h2><p>EDGE: Efficiency. The goal is less time spent finding facts and writing replies, without losing quality. A good reply answers every question, asks for what is missing, sends exceptions to the manager and promises nothing the policies do not allow. We have not measured time saved yet.</p><p>5A: Assistant, in a small web app. Flow: enquiry → facts → structured reply → source check → draft for human review. The model handles languages and messages with several questions. Our baseline is a keyword template that answers the first topic it finds, with the same facts.</p><p>The customer gives missing details. A support colleague checks damage claims and sends replies. The manager approves exceptions and refunds. The app only proposes these steps: it never sends a message or issues a refund. We kept a single model call rather than several agents, since the case is small.</p><h2>Team and reproduction</h2><p>Rémi Barbier: prototype, data setup, tests and documentation (with Codex). Pauline Perrotton: test cases and response validation.</p><p>Local version: Python 3 and a logged-in Codex CLI. Run <code>python3 server.py</code> and open <code>http://127.0.0.1:8524</code>. The online version is in <code>vercel/</code> and uses <code>openai/gpt-4.1</code> through Vercel AI Gateway. The results below come from the local version.</p><p>Tests: <code>python3 -m unittest test_workflow test_server</code> (14 tests) and <code>python3 run_evaluation.py</code> (12 cases). The expected answers are never shown to the model, and source quotes are checked word for word.</p><h2>Evaluation</h2><p>M1–M5 come from the brief, V6–V12 are variations we wrote. Both methods get the same messages and facts. An automatic check covers topics, sources and manager routing, then we reviewed the content of each reply with Codex.</p>',f'<p>The 12 local runs took {r["inference"]["elapsed_seconds"]:.0f} seconds in total (including CLI startup), against {r["baseline_seconds"]*1000:.2f} ms for the template. Cost and time saved are not measured.</p>','<p>We changed the prompt once after the first run, to stop internal notes from appearing in customer replies. So these 12 cases are a development set, not an unseen test.</p><table><tr><th>Case / input</th><th>Expected behaviour</th><th>Template result</th><th>Assistant result</th></tr>']
for row in r['rows']:
 id=row['id'];cells=[id+' · '+row['input'],row['expected']['checks'],('Pass' if a[id]['baseline']['pass'] else 'Needs work')+': '+notes[id][0],('Pass' if a[id]['prototype']['pass'] else 'Needs work')+': '+notes[id][1]]
 parts.append('<tr>'+''.join('<td>'+E(c)+'</td>' for c in cells)+'</tr>')
parts+=['</table><p>Result: assistant 12/12, template 3/12.</p><h2>Raw outputs</h2>']
for row in r['rows']:parts.append('<details><summary>'+E(row['id'])+' outputs</summary><pre>'+E(json.dumps({'template':row['baseline'],'assistant':row['prototype']},ensure_ascii=False,indent=2))+'</pre></details>')
parts+=['<h2>Limits and next steps</h2><p>A valid quote does not guarantee that every sentence is right, so staff still review each draft. Photos are not analysed and there is no live tracking. Next: test on new messages, have support staff review the drafts, and measure time and cost.</p><h2>Submission</h2><p>This page, the solution archive and the 3:29 demo video, which shows the local version.</p></body></html>']
(ROOT/'appendix.html').write_text(''.join(parts));(ROOT/'vercel/public/appendix.html').write_text(''.join(parts))
